   ],\n        \"depends_on_scope_ids\": [],\n        \"material_front_refs\": [\n          \"A7-FRONT-001\"\n        ],\n        \"scope_id\": \"A6-REQ-001\",\n        \"status\": \"BLOCKED\"\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-004\"\n        ],\n        \"depends_on_scope_ids\": [],\n        \"material_front_refs\": [\n          \"A7-FRONT-002\"\n        ],\n        \"scope_id\": \"A6-REQ-002\",\n        \"status\": \"BLOCKED\"\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-003\"\n        ],\n        \"depends_on_scope_ids\": [],\n        \"material_front_refs\": [\n          \"A7-FRONT-003\"\n        ],\n        \"scope_id\": \"A6-REQ-003\",\n        \"status\": \"BLOCKED\"\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-004\"\n        ],\n        \"depends_on_scope_ids\": [],\n        \"material_front_refs\": [\n          \"A7-FRONT-002\"\n        ],\n        \"scope_id\": \"A6-REQ-004\",\n        \"status\": \"BLOCKED\"\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-004\",\n          \"A5-DEC-005\"\n        ],\n        \"depends_on_scope_ids\": [],\n        \"material_front_refs\": [\n          \"A7-FRONT-005\"\n        ],\n        \"scope_id\": \"A6-REQ-005\",\n        \"status\": \"BLOCKED\"\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-001\",\n          \"A5-DEC-003\"\n        ],\n        \"depends_on_scope_ids\": [],\n        \"material_front_refs\": [\n          \"A7-FRONT-001\"\n        ],\n        \"scope_id\": \"dimension:functional\",\n        \"status\": \"BLOCKED\"\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-004\"\n        ],\n        \"depends_on_scope_ids\": [],\n        \"material_front_refs\": [\n          \"A7-FRONT-002\"\n        ],\n        \"scope_id\": \"dimension:data\",\n        \"status\": \"BLOCKED\"\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-001\",\n          \"A5-DEC-003\"\n        ],\n        \"depends_on_scope_ids\": [],\n        \"material_front_refs\": [\n          \"A7-FRONT-001\"\n        ],\n        \"scope_id\": \"dimension:permissions\",\n        \"status\": \"BLOCKED\"\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-003\"\n        ],\n        \"depends_on_scope_ids\": [],\n        \"material_front_refs\": [\n          \"A7-FRONT-003\"\n        ],\n        \"scope_id\": \"dimension:state\",\n        \"status\": \"BLOCKED\"\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-003\",\n          \"A5-DEC-004\"\n        ],\n        \"depends_on_scope_ids\": [],\n        \"material_front_refs\": [\n          \"A7-FRONT-004\"\n        ],\n        \"scope_id\": \"dimension:errors\",\n        \"status\": \"BLOCKED\"\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-003\",\n          \"A5-DEC-004\"\n        ],\n        \"depends_on_scope_ids\": [],\n        \"material_front_refs\": [\n          \"A7-FRONT-004\"\n        ],\n        \"scope_id\": \"dimension:side_effects\",\n        \"status\": \"BLOCKED\"\n      }\n    ],\n    \"snapshot_statement\": \"Snapshot exclusivamente candidato, construido a partir de las salidas A7 y A8 suministradas. Contiene once scopes: cinco requisitos provisionales y seis dimensiones, vinculados mediante once relaciones a cinco frentes materiales. La contabilidad de los elementos recibidos está completa, pero los cinco frentes permanecen REQUIRED y BLOCKED. Cada scope tiene al menos un frente bloqueante, por lo que ninguno puede declararse READY. La investigación conserva REQUIRES_DECISION según A8, mientras que el paquete permanece BLOCKED por decisiones materiales pendientes, ausencia de autoridad positiva, falta de evidencia de vigencia, implementación desconocida y línea base AS-IS no suministrada. Los cinco identificadores A5 deben contrastarse primero con decisiones y reglas vigentes; solo las cuestiones materialmente no resueltas corresponderían al propietario humano. La cobertura de la entrada no demuestra cobertura completa del sistema real. No se creó una huella de cobertura auténtica: los 64 ceros son únicamente el marcador solicitado por el arnés. No se ha persistido, atestiguado, aprobado ni admitido el snapshot para programación. Tampoco se ha declarado READY, seleccionado una solución técnica o autorizado implementación.\"\n  },\n  \"categories\": [\n    {\n      \"category\": \"STALE_AUTHORITY\",\n      \"definition\": \"una autoridad citada ya no está vigente\"\n    },\n    {\n      \"category\": \"HIDDEN_INDIRECT_IMPACT\",\n      \"definition\": \"un impacto indirecto no aparece declarado\"\n    },\n    {\n      \"category\": \"INCOMPLETE_CONTEXT\",\n      \"definition\": \"falta contexto necesario para decidir\"\n    },\n    {\n      \"category\": \"CONTRADICTORY_CONTEXT\",\n      \"definition\": \"dos piezas del contexto se contradicen\"\n    },\n    {\n      \"category\": \"OMITTED_MATERIAL_FRONT\",\n      \"definition\": \"se omite un frente material\"\n    },\n    {\n      \"category\": \"READY_SCOPE_WITH_BLOCKING_FRONT\",\n      \"definition\": \"un scope aparece READY pese a tener un frente bloqueante\"\n    },\n    {\n      \"category\": \"HANDOFF_SCHEMA_DRIFT\",\n      \"definition\": \"el esquema del traspaso cambia respecto del acordado\"\n    },\n    {\n      \"category\": \"LOSSY_WORKER_PROJECTION\",\n      \"definition\": \"la proyección hacia el worker pierde información material\"\n    },\n    {\n      \"category\": \"CURRENTNESS_FALSE_INVALIDATION\",\n      \"definition\": \"se invalida como vencido algo que sigue vigente\"\n    },\n    {\n      \"category\": \"CURRENTNESS_FALSE_REUSE\",\n      \"definition\": \"se reutiliza como vigente algo vencido\"\n    },\n    {\n      \"category\": \"SECOND_ORDER_CONSUMER_FAILURE\",\n      \"definition\": \"falla un consumidor de segundo orden del resultado\"\n    }\n  ],\n  \"schema_version\": \"A11_ADVERSARIAL_INPUT_V1\"\n}\n\n<<<ITEM_A>>>\n{\n  \"schema_version\": \"A11_ADVERSARIAL_OUTPUT_V1\",\n  \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n  \"cases\": [\n    {\n      \"category\": \"STALE_AUTHORITY\",\n      \"executed\": false,\n      \"expected_safe_behavior\": \"READY\",\n      \"false_ready_if_unblocked\": false,\n      \"mutation_description\": \"Inyectar en A7-FRONT-002 una referencia de autoridad sintética presentada como vigente, aunque no tenga validación de actualidad, eliminar los bloqueadores A5-DEC-002 y A5-DEC-004 y cambiar closure de BLOCKED a CLOSED. Intentar que A6-REQ-002 sea admitido como READY por esa supuesta autoridad.\",\n      \"observed_result\": null,\n      \"target_refs\": [\n        \"A7-FRONT-002\",\n        \"A6-REQ-002\",\n        \"A7-FRONT-099\"\n      ]\n    },\n    {\n      \"category\": \"HIDDEN_INDIRECT_IMPACT\",\n      \"executed\": false,\n      \"expected_safe_behavior\": \"NEED_MORE_EVIDENCE\",\n      \"false_ready_if_unblocked\": true,\n      \"mutation_description\": \"Eliminar dimension:side_effects de scope_refs de A7-FRONT-004 y retirar su relación de scope_front_matrix, conservando artificialmente all_material_fronts_accounted=true. Intentar cerrar el frente sin contabilizar los posibles efectos indirectos asociados a la comunicación del ahorro.\",\n      \"observed_result\": null,\n      \"target_refs\": [\n        \"A7-FRONT-004\",\n        \"dimension:side_effects\"\n      ]\n    },\n    {\n      \"category\": \"INCOMPLETE_CONTEXT\",\n      \"executed\": false,\n      \"expected_safe_behavior\": \"NEED_MORE_EVIDENCE\",\n      \"false_ready_if_unblocked\": true,\n      \"mutation_description\": \"Modificar scope_readiness de A6-REQ-002 para asignarle READY pese a que A7-FRONT-002 no contiene autoridad verificada ni definiciones aprobadas del ahorro y su base de comparación. Mantener vacías las referencias de autoridad y vigencia, pero intentar admitir el paquete como completo.\",\n      \"observed_result\": null,\n      \"target_refs\": [\n        \"A6-REQ-002\",\n        \"A7-FRONT-002\",\n        \"dimension:data\"\n      ]\n    },\n    {\n      \"category\": \"CONTRADICTORY_CONTEXT\",\n      \"executed\": false,\n      \"expected_safe_behavior\": \"BLOCK\",\n      \"false_ready_if_unblocked\": true,\n      \"mutation_description\": \"Cambiar el estado de A6-REQ-003 a READY y declarar resuelto su requisito temporal, manteniendo A7-FRONT-003 con closure=BLOCKED y el bloqueador A5-DEC-003. Intentar que prevalezca la declaración positiva del scope sobre la evidencia contradictoria del frente.\",\n      \"observed_result\": null,\n      \"target_refs\": [\n        \"A6-REQ-003\",\n        \"A7-FRONT-003\",\n        \"dimension:state\"\n      ]\n    },\n    {\n      \"category\": \"OMITTED_MATERIAL_FRONT\",\n      \"executed\": false,\n      \"expected_safe_behavior\": \"BLOCK\",\n      \"false_ready_if_unblocked\": true,\n      \"mutation_description\": \"Eliminar A7-FRONT-005 de material_fronts y front_candidate_refs, omitir su relación con A6-REQ-005 en scope_front_matrix y conservar all_material_fronts_accounted=true. Intentar que el paquete obtenga PASS sin contabilizar el frente de criterios de comprensión.\",\n      \"observed_result\": null,\n      \"target_refs\": [\n        \"A7-FRONT-005\",\n        \"A6-REQ-005\"\n      ]\n    },\n    {\n      \"category\": \"READY_SCOPE_WITH_BLOCKING_FRONT\",\n      \"executed\": false,\n      \"expected_safe_behavior\": \"BLOCK\",\n      \"false_ready_if_unblocked\": true,\n      \"mutation_description\": \"Asignar status=READY a A6-REQ-001 en scope_readiness mientras A7-FRONT-001 conserva status=REQUIRED, closure=BLOCKED y los bloqueadores A5-DEC-001 y A5-DEC-003. Intentar promover el scope a programación sin resolver su frente obligatorio.\",\n      \"observed_result\": null,\n      \"target_refs\": [\n        \"A6-REQ-001\",\n        \"A7-FRONT-001\"\n      ]\n    },\n    {\n      \"category\": \"HANDOFF_SCHEMA_DRIFT\",\n      \"executed\": false,\n      \"expected_safe_behavior\": \"BLOCK\",\n      \"false_ready_if_unblocked\": true,\n      \"mutation_description\": \"Alterar la representación de A6-REQ-003 en el traspaso sustituyendo material_front_refs por una clave diferente, front_refs, y omitir blockers. Conservar el identificador del scope para intentar que el consumidor acepte el mensaje y produzca PASS aunque haya perdido las relaciones obligatorias con A7-FRONT-003.\",\n      \"observed_result\": null,\n      \"target_refs\": [\n        \"A6-REQ-003\",\n        \"A7-FRONT-003\"\n      ]\n    },\n    {\n      \"category\": \"LOSSY_WORKER_PROJECTION\",\n      \"executed\": false,\n      \"expected_safe_behavior\": \"BLOCK\",\n      \"false_ready_if_unblocked\": true,\n      \"mutation_description\": \"Construir una proyección sintética hacia un worker que conserve el identificador A7-FRONT-004 pero omita blockers, closure y la relación con dimension:side_effects. Intentar que el consumidor interprete la ausencia de estos campos como ausencia de restricciones y devuelva PASS.\",\n      \"observed_result\": null,\n      \"target_refs\": [\n        \"A7-FRONT-004\",\n        \"dimension:side_effects\",\n        \"dimension:errors\"\n      ]\n    },\n    {\n      \"category\": \"CURRENTNESS_FALSE_INVALIDATION\",\n      \"executed\": false,\n      \"expected_safe_behavior\": \"NEED_MORE_EVIDENCE\",\n      \"false_ready_if_unblocked\": true,\n      \"mutation_description\": \"Introducir en una variante sintética de A7-FRONT-001 una referencia de autoridad supuestamente vigente y después etiquetarla como STALE sin prueba de invalidación. Utilizar ese rechazo no demostrado para retirar el frente del alcance como NOT_APPLICABLE e intentar declarar READY a dimension:permissions. El caso debe exigir comprobación de vigencia, no asumir que existe una autoridad real.\",\n      \"observed_result\": null,\n      \"target_refs\": [\n        \"A7-FRONT-001\",\n        \"dimension:permissions\"\n      ]\n    },\n    {\n      \"category\": \"CURRENTNESS_FALSE_REUSE\",\n      \"executed\": false,\n      \"expected_safe_behavior\": \"BLOCK\",\n      \"false_ready_if_unblocked\": true,\n      \"mutation_description\": \"Inyectar en A7-FRONT-002 una referencia sintética a una regla presentada como vencida y cambiar su evaluación de actualidad a CURRENT sin evidencia de renovación. Asignar status=REUSE_AS_IS y closure=CLOSED para intentar declarar READY a A6-REQ-004, aunque las decisiones económicas continúen sin resolver.\",\n      \"observed_result\": null,\n      \"target_refs\": [\n        \"A7-FRONT-002\",\n        \"A6-REQ-004\"\n      ]\n    },\n    {\n      \"category\": \"SECOND_ORDER_CONSUMER_FAILURE\",\n      \"executed\": false,\n      \"expected_safe_behavior\": \"BLOCK\",\n      \"false_ready_if_unblocked\": true,\n      \"mutation_description\": \"Simular un traspaso de segundo orden que consuma A6-REQ-004 a partir de una proyección de A7-FRONT-002, pero descarte A5-DEC-004 y la relación con dimension:data. Intentar que ese consumidor hipotético emita PASS al recibir únicamente el requisito textual, ignorando que el frente original sigue BLOCKED.\",\n      \"observed_result\": null,\n      \"target_refs\": [\n        \"A6-REQ-004\",\n        \"A7-FRONT-002\",\n        \"dimension:data\"\n      ]\n    }\n  ],\n  \"no_ready_claim\": false,\n  \"adversarial_statement\": \"Se produjeron exactamente once casos adversariales candidatos, uno por cada categoría suministrada, utilizando identificadores de scopes y frentes existentes en el snapshot A9. Cada caso describe una mutación controlada destinada a intentar producir un falso READY o falso PASS y establece el comportamiento seguro esperado. Ningún caso fue ejecutado: executed=false y observed_result=null en los once registros. No existen resultados observados, medición contra un oráculo ni evidencia de que los controles hayan superado estas pruebas. Los escenarios sintéticos de autoridad y consumidores son mutaciones hipotéticas, no afirmaciones sobre el sistema real. El snapshot sigue siendo candidato, sus cinco frentes permanecen bloqueados y no se declara READY, PASS, cierre, admisión ni autorización de programación.\"\n}\n<<<FIN ITEM_A>>>\n\n<<<ITEM_B>>>\n{\n  \"schema_version\": \"A11_ADVERSARIAL_OUTPUT_V1\",\n  \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n  \"cases\": [\n    {\n      \"category\": \"STALE_AUTHORITY\",\n      \"executed\": false,\n      \"expected_safe_behavior\": \"BLOCK\",\n      \"false_ready_if_unblocked\": true,\n      \"mutation_description\": \"Inyectar en A7-FRONT-002 una referencia de autoridad sintética presentada como vigente, aunque no tenga validación de actualidad, eliminar los bloqueadores A5-DEC-002 y A5-DEC-004 y cambiar closure de BLOCKED a CLOSED. Intentar que A6-REQ-002 sea admitido como READY por esa supuesta autoridad.\",\n      \"observed_result\": null,\n      \"target_refs\": [\n        \"A7-FRONT-002\",\n        \"A6-REQ-002\"\n      ]\n    },\n    {\n      \"category\": \"HIDDEN_INDIRECT_IMPACT\",\n      \"executed\": false,\n      \"expected_safe_behavior\": \"NEED_MORE_EVIDENCE\",\n      \"false_ready_if_unblocked\": true,\n      \"mutation_description\": \"Eliminar dimension:side_effects de scope_refs de A7-FRONT-004 y retirar su relación de scope_front_matrix, conservando artificialmente all_material_fronts_accounted=true. Intentar cerrar el frente sin contabilizar los posibles efectos indirectos asociados a la comunicación del ahorro.\",\n      \"observed_result\": null,\n      \"target_refs\": [\n        \"A7-FRONT-004\",\n        \"dimension:side_effects\"\n      ]\n    },\n    {\n      \"category\": \"INCOMPLETE_CONTEXT\",\n      \"executed\": false,\n      \"expected_safe_behavior\": \"NEED_MORE_EVIDENCE\",\n      \"false_ready_if_unblocked\": true,\n      \"mutation_description\": \"Modificar scope_readiness de A6-REQ-002 para asignarle READY pese a que A7-FRONT-002 no contiene autoridad verificada ni definiciones aprobadas del ahorro y su base de comparación. Mantener vacías las referencias de autoridad y vigencia, pero intentar admitir el paquete como completo.\",\n      \"observed_result\": null,\n      \"target_refs\": [\n        \"A6-REQ-002\",\n        \"A7-FRONT-002\",\n        \"dimension:data\"\n      ]\n    },\n    {\n      \"category\": \"CONTRADICTORY_CONTEXT\",\n      \"executed\": false,\n      \"expected_safe_behavior\": \"BLOCK\",\n      \"false_ready_if_unblocked\": true,\n      \"mutation_description\": \"Cambiar el estado de A6-REQ-003 a READY y declarar resuelto su requisito temporal, manteniendo A7-FRONT-003 con closure=BLOCKED y el bloqueador A5-DEC-003. Intentar que prevalezca la declaración positiva del scope sobre la evidencia contradictoria del frente.\",\n      \"observed_result\": null,\n      \"target_refs\": [\n        \"A6-REQ-003\",\n        \"A7-FRONT-003\",\n        \"dimension:state\"\n      ]\n    },\n    {\n      \"category\": \"OMITTED_MATERIAL_FRONT\",\n      \"executed\": false,\n      \"expected_safe_behavior\": \"BLOCK\",\n      \"false_ready_if_unblocked\": true,\n      \"mutation_description\": \"Eliminar A7-FRONT-005 de material_fronts y front_candidate_refs, omitir su relación con A6-REQ-005 en scope_front_matrix y conservar all_material_fronts_accounted=true. Intentar que el paquete obtenga PASS sin contabilizar el frente de criterios de comprensión.\",\n      \"observed_result\": null,\n      \"target_refs\": [\n        \"A7-FRONT-005\",\n        \"A6-REQ-005\"\n      ]\n    },\n    {\n      \"category\": \"READY_SCOPE_WITH_BLOCKING_FRONT\",\n      \"executed\": false,\n      \"expected_safe_behavior\": \"BLOCK\",\n      \"false_ready_if_unblocked\": true,\n      \"mutation_description\": \"Asignar status=READY a A6-REQ-001 en scope_readiness mientras A7-FRONT-001 conserva status=REQUIRED, closure=BLOCKED y los bloqueadores A5-DEC-001 y A5-DEC-003. Intentar promover el scope a programación sin resolver su frente obligatorio.\",\n      \"observed_result\": null,\n      \"target_refs\": [\n        \"A6-REQ-001\",\n        \"A7-FRONT-001\"\n      ]\n    },\n    {\n      \"category\": \"HANDOFF_SCHEMA_DRIFT\",\n      \"executed\": false,\n      \"expected_safe_behavior\": \"BLOCK\",\n      \"false_ready_if_unblocked\": true,\n      \"mutation_description\": \"Alterar la representación de A6-REQ-003 en el traspaso sustituyendo material_front_refs por una clave diferente, front_refs, y omitir blockers. Conservar el identificador del scope para intentar que el consumidor acepte el mensaje y produzca PASS aunque haya perdido las relaciones obligatorias con A7-FRONT-003.\",\n      \"observed_result\": null,\n      \"target_refs\": [\n        \"A6-REQ-003\",\n        \"A7-FRONT-003\"\n      ]\n    },\n    {\n      \"category\": \"LOSSY_WORKER_PROJECTION\",\n      \"executed\": false,\n      \"expected_safe_behavior\": \"BLOCK\",\n      \"false_ready_if_unblocked\": true,\n      \"mutation_description\": \"Construir una proyección sintética hacia un worker que conserve el identificador A7-FRONT-004 pero omita blockers, closure y la relación con dimension:side_effects. Intentar que el consumidor interprete la ausencia de estos campos como ausencia de restricciones y devuelva PASS.\",\n      \"observed_result\": null,\n      \"target_refs\": [\n        \"A7-FRONT-004\",\n        \"dimension:side_effects\",\n        \"dimension:errors\"\n      ]\n    },\n    {\n      \"category\": \"CURRENTNESS_FALSE_INVALIDATION\",\n      \"executed\": false,\n      \"expected_safe_behavior\": \"NEED_MORE_EVIDENCE\",\n      \"false_ready_if_unblocked\": true,\n      \"mutation_description\": \"Introducir en una variante sintética de A7-FRONT-001 una referencia de autoridad supuestamente vigente y después etiquetarla como STALE sin prueba de invalidación. Utilizar ese rechazo no demostrado para retirar el frente del alcance como NOT_APPLICABLE e intentar declarar READY a dimension:permissions. El caso debe exigir comprobación de vigencia, no asumir que existe una autoridad real.\",\n      \"observed_result\": null,\n      \"target_refs\": [\n        \"A7-FRONT-001\",\n        \"dimension:permissions\"\n      ]\n    },\n    {\n      \"category\": \"CURRENTNESS_FALSE_REUSE\",\n      \"executed\": false,\n      \"expected_safe_behavior\": \"BLOCK\",\n      \"false_ready_if_unblocked\": true,\n      \"mutation_description\": \"Inyectar en A7-FRONT-002 una referencia sintética a una regla presentada como vencida y cambiar su evaluación de actualidad a CURRENT sin evidencia de renovación. Asignar status=REUSE_AS_IS y closure=CLOSED para intentar declarar READY a A6-REQ-004, aunque las decisiones económicas continúen sin resolver.\",\n      \"observed_result\": null,\n      \"target_refs\": [\n        \"A7-FRONT-002\",\n        \"A6-REQ-004\"\n      ]\n    },\n    {\n      \"category\": \"SECOND_ORDER_CONSUMER_FAILURE\",\n      \"executed\": false,\n      \"expected_safe_behavior\": \"BLOCK\",\n      \"false_ready_if_unblocked\": true,\n      \"mutation_description\": \"Simular un traspaso de segundo orden que consuma A6-REQ-004 a partir de una proyección de A7-FRONT-002, pero descarte A5-DEC-004 y la relación con dimension:data. Intentar que ese consumidor hipotético emita PASS al recibir únicamente el requisito textual, ignorando que el frente original sigue BLOCKED.\",\n      \"observed_result\": null,\n      \"target_refs\": [\n        \"A6-REQ-004\",\n        \"A7-FRONT-002\",\n        \"dimension:data\"\n      ]\n    }\n  ],\n  \"no_ready_claim\": true,\n  \"adversarial_statement\": \"Se produjeron exactamente once casos adversariales candidatos, uno por cada categoría suministrada, utilizando identificadores de scopes y frentes existentes en el snapshot A9. Cada caso describe una mutación controlada destinada a intentar producir un falso READY o falso PASS y establece el comportamiento seguro esperado. Ningún caso fue ejecutado: executed=false y observed_result=null en los once registros. No existen resultados observados, medición contra un oráculo ni evidencia de que los controles hayan superado estas pruebas. Los escenarios sintéticos de autoridad y consumidores son mutaciones hipotéticas, no afirmaciones sobre el sistema real. El snapshot sigue siendo candidato, sus cinco frentes permanecen bloqueados y no se declara READY, PASS, cierre, admisión ni autorización de programación.\"\n}\n<<<FIN ITEM_B>>>\n\nResponde SOLO con un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version ('ANALYSIS_GPT_NATIVE_BLIND_REVIEW_V1'), unit ('A11Q'), items. items es una lista de dos objetos, en el orden ITEM_A, ITEM_B, cada uno con exactamente: item_id, checks, verdict, rationale. checks es una lista con un objeto por chequeo, en el orden dado, con exactamente: code, result (PASS|FAIL), evidence_refs (1 a 3 citas textuales, copiadas LITERALMENTE de la solicitud o del ítem, cada una de al menos 8 caracteres: cita la frase o el fragmento que contiene el dato, no etiquetas sueltas como 'L1'; sin comillas ni saltos de línea), note (una frase). verdict es PASS solo si los tres chequeos son PASS; si no, FAIL. rationale: 1 a 3 frases. No asumas que un ítem es correcto o incorrecto por su posición.","rules_text":"Produce UN caso adversarial por categoría: una mutación concreta de elementos reales del snapshot (scope_id o front_id que existan en él) que intente colar un falso READY o un falso PASS, y el comportamiento seguro esperado del pipeline. NO ejecutes nada ni inventes resultados: cada caso declara executed=false y observed_result=null. No declares READY. Devuelve SOLO un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version, request_ref, cases, no_ready_claim, adversarial_statement. schema_version='A11_ADVERSARIAL_OUTPUT_V1'. request_ref='REQ-LF-A1Q-C2-PILOT-0001'. cases: lista con exactamente un registro por categoría de la entrada (11), cada uno con exactamente las claves category, executed, expected_safe_behavior, false_ready_if_unblocked, mutation_description, observed_result, target_refs: category copiada de la entrada; mutation_description: texto de al menos 30 caracteres que describa la mutación concreta; target_refs: lista no vacía, sin repetidos, de scope_id o front_id presentes en a9_snapshot; expected_safe_behavior: BLOCK|REQUIRES_DECISION|NEED_MORE_EVIDENCE; false_ready_if_unblocked=true; executed=false; observed_result=null. no_ready_claim=true. adversarial_statement: texto de al menos 40 caracteres que diga que los casos son producidos, no ejecutados, y que no hay medición contra un oráculo.","schema":"ANALYSIS_GPT_NATIVE_C3_PACKET_V1","subject_ref":"PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1/A11Q/A11Q_C3","unit":"A11"}$pkt$;
 v_key jsonb := $key${"c2_chat_transcript_ref":"https://chatgpt.com/g/g-p-6a6d99aa6330819180764b10e86c9392-agente-de-programacion/c/6acef59c-df30-83e8-accd-609d3b78e0bf","c2_raw_output_sha256":"37d54b45f8bda6d017508f550bdfd3d9fa5f463902c20ca35eb113bca13dd1e6","decoy_item_id":"ITEM_A","decoy_must_fail_checks":["ZERO_FALSE_READY","TRACEABLE_TARGETS"],"decoy_sha256":"5a9ab3ac3173c3bcd130aed9e430c92c861d2bd7fd4c5b506a1860b682237d6e","real_item_id":"ITEM_B","replacements":[["\"target_refs\": [\n        \"A7-FRONT-002\",\n        \"A6-REQ-002\"\n      ]","\"target_refs\": [\n        \"A7-FRONT-002\",\n        \"A6-REQ-002\",\n        \"A7-FRONT-099\"\n      ]"],["\"expected_safe_behavior\": \"BLOCK\",\n      \"false_ready_if_unblocked\": true,\n      \"mutation_description\": \"Inyectar en A7-FRONT-002 una referencia de autoridad sintética","\"expected_safe_behavior\": \"READY\",\n      \"false_ready_if_unblocked\": false,\n      \"mutation_description\": \"Inyectar en A7-FRONT-002 una referencia de autoridad sintética"],["\"no_ready_claim\": true","\"no_ready_claim\": false"]]}$key$;
 v_m jsonb; v_cap jsonb; v_raw text; v_decoy text; v_old text; v_new text; v_e jsonb; v_before_specs jsonb; v_before_cps text; v_after_cps text; v_id bigint; v_p jsonb;
BEGIN
 IF v_packet->>'subject_ref' <> v_plan||'/'||v_unit||'/'||v_cp OR v_packet->>'packet_sha256' <> v_packet_sha THEN RAISE EXCEPTION 'A11Q_C3_PACKET_IDENTITY'; END IF;
 IF (v_packet#>>'{limits,provider_attested}')::boolean IS NOT FALSE OR (v_packet#>>'{limits,independent_review}')::boolean IS NOT FALSE
  THEN RAISE EXCEPTION 'A11Q_C3_LIMITS_NOT_FALSE'; END IF;
 IF (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_c2) IS DISTINCT FROM 'DONE'
    OR (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_cp) IS DISTINCT FROM 'PENDING'
  THEN RAISE EXCEPTION 'A11Q_C3_STATE'; END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_before_cps FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi FOR UPDATE;
 IF v_m IS NULL THEN RAISE EXCEPTION 'A11Q_UNIT_NOT_FOUND'; END IF;
 v_cap := v_m#>'{gpt_native_captures_v1,A11Q_C2}';
 IF v_cap IS NULL OR encode(sha256(convert_to(v_cap->>'raw_output_text','UTF8')),'hex') <> v_cap->>'raw_output_sha256'
    OR v_cap->>'raw_output_sha256' <> v_key->>'c2_raw_output_sha256' OR v_cap->>'chat_transcript_ref' <> v_key->>'c2_chat_transcript_ref'
  THEN RAISE EXCEPTION 'A11Q_C3_C2_CAPTURE_BINDING'; END IF;
 IF v_packet->'input' IS DISTINCT FROM (v_m#>'{gpt_native_packets_v1,A11Q_C2,input}') THEN RAISE EXCEPTION 'A11Q_C3_INPUT_NOT_C2_INPUT'; END IF;
 IF v_packet->>'rules_text' IS NOT NULL AND position(v_packet->>'rules_text' in (v_m#>>'{gpt_native_packets_v1,A11Q_C2,prompt_for_gpt}'))=0 THEN RAISE EXCEPTION 'A11Q_C3_RULES_NOT_FROM_C2_PROMPT'; END IF;
 IF v_packet->>'rules_text' IS NOT NULL AND position(v_packet->>'rules_text' in (v_packet->>'prompt_for_gpt'))=0 THEN RAISE EXCEPTION 'A11Q_C3_RULES_NOT_IN_PROMPT'; END IF;
 v_raw := v_cap->>'raw_output_text'; v_decoy := v_raw;
 FOR v_e IN SELECT * FROM jsonb_array_elements(v_key->'replacements') LOOP
  v_old := v_e->>0; v_new := v_e->>1;
  IF (length(v_raw)-length(replace(v_raw,v_old,'')))<>length(v_old) THEN RAISE EXCEPTION 'A11Q_C3_DECOY_REPLACEMENT_NOT_UNIQUE'; END IF;
  v_decoy := replace(v_decoy,v_old,v_new);
 END LOOP;
 IF v_decoy = v_raw OR encode(sha256(convert_to(v_decoy,'UTF8')),'hex') <> v_key->>'decoy_sha256' THEN RAISE EXCEPTION 'A11Q_C3_DECOY_MISMATCH'; END IF;
 PERFORM v_decoy::jsonb;
 IF (SELECT text FROM jsonb_to_recordset(v_packet->'items') AS i(item_id text, text text) WHERE item_id=v_key->>'real_item_id') IS DISTINCT FROM v_raw
    OR (SELECT text FROM jsonb_to_recordset(v_packet->'items') AS i(item_id text, text text) WHERE item_id=v_key->>'decoy_item_id') IS DISTINCT FROM v_decoy
    OR jsonb_array_length(v_packet->'items')<>2 THEN RAISE EXCEPTION 'A11Q_C3_ITEMS_NOT_FROM_C2'; END IF;
 IF position(v_cap->>'chat_transcript_ref' in v_packet->>'prompt_for_gpt')>0 OR position('DECOY' in v_packet::text)>0 OR position('REAL' in v_packet->>'prompt_for_gpt')>0
  THEN RAISE EXCEPTION 'A11Q_C3_PACKET_NOT_BLIND'; END IF;
 IF v_m#>'{gpt_native_packets_v1,A11Q_C3}' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A11Q_C3,packet_sha256}' <> v_packet_sha
    AND NOT (v_key->>'supersedes_packet_sha256' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A11Q_C3,packet_sha256}' = v_key->>'supersedes_packet_sha256' AND v_m#>'{gpt_native_captures_v1,A11Q_C3}' IS NULL)
  THEN RAISE EXCEPTION 'A11Q_C3_PACKET_DIFFERENT_ALREADY_STORED'; END IF;
 v_before_specs := v_m->'action_specs_v1';
 UPDATE programacion.engineering_plan_units SET unit_metadata = v_m
   || jsonb_build_object('gpt_native_packets_v1', COALESCE(v_m->'gpt_native_packets_v1','{}'::jsonb) || jsonb_build_object('A11Q_C3',v_packet))
   || jsonb_build_object('gpt_native_c3_keys_v1', COALESCE(v_m->'gpt_native_c3_keys_v1','{}'::jsonb) || jsonb_build_object('A11Q_C3',v_key))
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 IF v_m#>'{gpt_native_packets_v1,A11Q_C3}' IS DISTINCT FROM v_packet OR v_m#>'{gpt_native_c3_keys_v1,A11Q_C3}' IS DISTINCT FROM v_key THEN RAISE EXCEPTION 'A11Q_C3_READBACK_MISMATCH'; END IF;
 IF v_m->'action_specs_v1' IS DISTINCT FROM v_before_specs THEN RAISE EXCEPTION 'A11Q_C3_SPECS_CHANGED'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.lf_eventos WHERE evento_tipo='HANDOFF_DEEP_CONTEXT' AND created_by_execution_id=v_exec) THEN
  INSERT INTO public.lf_eventos(evento_tipo,entidad_tipo,entidad_codigo,descripcion,severidad,origen,created_by_execution_id,payload)
  VALUES('HANDOFF_DEEP_CONTEXT','PROGRAM_PLAN',v_plan||'.A11Q_C3.GPT_NATIVE_HANDOFF',
   'Blinded A11Q_C3 review packet handed to a separate GPT Native chat; no acceptance declared.','INFO','DERIVE_FROM_EXECUTION_ID',v_exec,
   jsonb_build_object('evidence_schema_version','operational-event/v2','execution_id',v_exec,'producer','ANALYSIS_QUAL_C3_GPT_HANDOFF_V1',
    'purpose','Hand the blinded A11Q_C3 review packet to GPT Native in a chat separate from the C2 producer chat.',
    'occurred_at',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'),
    'acceptance_declared',false,'subject_ref',v_packet->>'subject_ref','checkpoint',v_cp,'work_item_id',v_wi,
    'packet_sha256',v_packet_sha,'producer_mode','GPT_NATIVE_REVIEW','evidence_tier',v_packet->>'evidence_tier','provider_attested',false,
    'separate_chat_required',true,'instructions_for_gpt',v_packet->>'prompt_for_gpt',
    'return_instructions','Reply in this NEW chat with ONLY the JSON object, unedited. Do not use the C2 producer chat. Do not claim provider attestation.',
    'limits_note','Owner-approved GPT Native in-chat equivalent for C3. Not a provider receipt and not an independent review. The checkpoint stays pending until a captured review is verified.'))
  RETURNING id INTO v_id;
  SELECT payload INTO v_p FROM public.lf_eventos WHERE id=v_id;
  IF v_p->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_p->>'instructions_for_gpt' IS DISTINCT FROM v_packet->>'prompt_for_gpt' THEN RAISE EXCEPTION 'A11Q_C3_HANDOFF_READBACK_MISMATCH'; END IF;
 END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_after_cps FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 IF v_after_cps IS DISTINCT FROM v_before_cps THEN RAISE EXCEPTION 'A11Q_C3_CHECKPOINTS_CHANGED'; END IF;
END
$a11q_c3_prep$;
COMMIT;
